<script setup lang="ts">import {computed,ref} from "vue";import {Paperclip,Plus,Check,X} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import ZButton from "@/components/zs/ZButton.vue";import PageHeader from "@/components/zs/PageHeader.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Panel from "@/components/zs/Panel.vue";import SearchInput from "@/components/zs/SearchInput.vue";import StatCard from "@/components/zs/StatCard.vue";import Toolbar from "@/components/zs/Toolbar.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import SidePanel from "@/components/zs/SidePanel.vue";import ConfirmDialog from "@/components/zs/ConfirmDialog.vue";import Field from "@/components/zs/Field.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney,parseMoneyInput} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {ExpenseClaim} from "@/types/operations";setPageMeta("Expenses","Employee expense submission, receipt review, approval and reimbursement.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.expenses(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),query=ref(''),status=ref('all'),open=ref(false),target=ref<ExpenseClaim|null>(null),decision=ref<'approved'|'rejected'>('approved'),claimant=ref(''),category=ref('Travel'),amount=ref('');const rows=computed(()=>(s.data.value??[]).filter(e=>(!query.value||`${e.claimant} ${e.reference}`.toLowerCase().includes(query.value.toLowerCase()))&&(status.value==='all'||e.status===status.value)));const columns:Column[]=[{key:'ref',header:'Reference',class:'num font-medium'},{key:'claimant',header:'Claimant'},{key:'category',header:'Category'},{key:'date',header:'Date',class:'num'},{key:'amount',header:'Amount',align:'right',class:'num'},{key:'receipt',header:'Receipt'},{key:'status',header:'Status'},{key:'actions',header:''}];async function decide(){if(!target.value)return;await operationsRepository.updateExpenseStatus(c.activeCompanyId,target.value.id,decision.value);showToast(decision.value==='approved'?'Claim approved':'Claim rejected');target.value=null;await s.refresh()}function submit(){if(!claimant.value||!parseMoneyInput(amount.value)){showToast('Complete required fields','Enter a claimant and valid amount.','danger');return}open.value=false;showToast('Expense claim prepared','The preview claim awaits backend validation and approval.','info')}</script><template><AppShell><PageHeader title="Expenses" description="Claims, receipts and reimbursement status for the active company"><template #actions><ZButton @click="open=true"><Plus class="size-4"/>New claim</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Pending approval" :value="String(rows.filter(x=>x.status==='pending').length)" tone="warning"/><StatCard label="Approved" :value="String(rows.filter(x=>x.status==='approved').length)" tone="success"/><StatCard label="Reimbursed" :value="formatMoney(rows.filter(x=>x.status==='paid').reduce((a,x)=>a+x.amount,0))" tone="brand"/><StatCard label="Total claims" :value="formatMoney(rows.reduce((a,x)=>a+x.amount,0))"/></div><Panel><Toolbar><SearchInput v-model="query" placeholder="Search claimant or reference"/><select v-model="status" class="field w-40"><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="paid">Reimbursed</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1050"><template #ref="{row}:{row:ExpenseClaim}">{{row.reference}}</template><template #claimant="{row}">{{row.claimant}}</template><template #category="{row}">{{row.category}}</template><template #date="{row}">{{row.date}}</template><template #amount="{row}">{{formatMoney(row.amount)}}</template><template #receipt="{row}"><span v-if="row.receipt" class="inline-flex items-center gap-1 text-xs text-content-secondary"><Paperclip class="size-3"/>Attached</span><span v-else class="text-xs text-danger">Missing</span></template><template #status="{row}"><StatusBadge :status="row.status" :label="row.status==='paid'?'Reimbursed':undefined"/></template><template #actions="{row}"><div v-if="row.status==='pending'" class="flex gap-1"><ZButton variant="ghost" aria-label="Approve claim" @click="target=row;decision='approved'"><Check class="size-4"/></ZButton><ZButton variant="ghost" aria-label="Reject claim" @click="target=row;decision='rejected'"><X class="size-4"/></ZButton></div></template></DataTable></Panel><SidePanel :open="open" title="New expense claim" description="Attach evidence and submit for approval." @close="open=false"><form class="space-y-4" @submit.prevent="submit"><Field v-model="claimant" label="Claimant" required/><label class="block"><span class="label-caps">Category</span><select v-model="category" class="field mt-1.5 w-full"><option>Travel</option><option>Meals</option><option>Software</option><option>Office</option></select></label><Field v-model="amount" label="Amount (PKR)" required/><label class="block"><span class="label-caps">Receipt</span><input type="file" class="field mt-1.5 w-full"/></label><label class="block"><span class="label-caps">Business reason</span><textarea class="field mt-1.5 min-h-24 w-full"></textarea></label><ZButton type="submit">Submit claim</ZButton></form></SidePanel><ConfirmDialog :open="!!target" :title="decision==='approved'?'Approve claim?':'Reject claim?'" :message="decision==='approved'?'The claim will move to reimbursement review.':'The claimant will see the rejection state and reason.'" :confirm-label="decision==='approved'?'Approve':'Reject'" :tone="decision==='approved'?'brand':'danger'" @cancel="target=null" @confirm="decide"/></AppShell></template>